CREATE OR REPLACE FUNCTION public.can_call_member(_other uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND _other IS NOT NULL AND auth.uid()<>_other AND public.account_allowed(auth.uid()) AND public.account_allowed(_other) AND (public.has_role(auth.uid(),'admin') OR public.has_role(_other,'admin') OR public.has_paid_bell(auth.uid()) OR EXISTS(SELECT 1 FROM public.app_calls c WHERE c.caller_id=_other AND c.callee_id=auth.uid() AND c.ended_at IS NULL AND c.created_at>now()-interval '2 hours' AND public.has_paid_bell(c.caller_id))) AND (public.can_post_chat(NULL,_other) OR EXISTS(SELECT 1 FROM public.messages WHERE (sender_id=auth.uid() AND receiver_id=_other) OR (sender_id=_other AND receiver_id=auth.uid()))) $$;
ALTER FUNCTION public.sync_show_choice_bell_consent() SET search_path=public;